fn semantics_of(name: &str) -> Semantics {
    match name {
        "floating" => Semantics::Floating,
        "all-day" => Semantics::AllDay,
        _ => Semantics::Zoned,
    }
}

fn compare_expansion(case: &Value, label: &str) {
    let zone = zone_of(&text(case, "zone"));
    let rrule_text = text(case, "rrule");
    let start = text(case, "start");
    let from = text(case, "rangeFrom");
    let to = text(case, "rangeTo");
    let mut input = ExpandInput::new(&rrule_text, &start, &from, &to)
        .with_semantics(semantics_of(&text(case, "semantics")))
        .at_most(usize::try_from(case["maxInstances"].as_u64().unwrap_or(366)).unwrap_or(366));
    input.zone = zone.as_ref();
    let found = recurrence::expand(&input);
    let expected = case["occurrences"].as_array().expect("occurrences");
    assert_eq!(
        found.len(),
        expected.len(),
        "{label}: occurrence count (found {:?})",
        found
            .iter()
            .map(|item| item.wall_start.as_str())
            .collect::<Vec<_>>()
    );
    for (index, (occurrence, want)) in found.iter().zip(expected).enumerate() {
        assert_eq!(
            occurrence.start,
            text(want, "start"),
            "{label}[{index}]: start"
        );
        assert_eq!(
            occurrence.wall_start,
            text(want, "wallStart"),
            "{label}[{index}]: THE KEY"
        );
        assert_eq!(
            occurrence.overlap,
            want["overlap"].as_bool().unwrap_or_default(),
            "{label}[{index}]: overlap"
        );
    }
}

#[test]
fn every_zoned_expansion_agrees_with_v0() {
    let corpus = fixture("dst-cases.json");
    let cases = corpus["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 78);
    let mut occurrences = 0_usize;
    for case in cases {
        let label = format!(
            "{} / {} / {}",
            text(case, "zone"),
            text(case, "rrule"),
            text(case, "start")
        );
        compare_expansion(case, &label);
        occurrences += case["occurrences"].as_array().map_or(0, Vec::len);
    }
    assert!(occurrences > 400, "{occurrences} occurrences compared");
    // The cases the owner's RFC 5545 decision on #1173 FLIPPED from v0's answer
    // (a gap moves forward and counts, section 3.3.5; an implied day a month
    // lacks is skipped, section 3.3.10) say so, and each carries the answer
    // an independent implementation (python-dateutil with zoneinfo) gives.
    let flipped = cases
        .iter()
        .filter(|case| {
            case["flipped"]
                .as_str()
                .is_some_and(|why| why.contains("RFC 5545"))
        })
        .count();
    assert_eq!(
        flipped, 13,
        "one DST case and the implied-day cases of six zones"
    );
}

#[test]
fn every_floating_and_all_day_expansion_agrees_with_v0() {
    let corpus = fixture("dst-cases.json");
    for case in corpus["floating"].as_array().expect("floating") {
        let label = format!("{} / {}", text(case, "semantics"), text(case, "rrule"));
        compare_expansion(case, &label);
    }
}

#[test]
fn every_wall_clock_resolution_agrees_with_v0() {
    let corpus = fixture("dst-cases.json");
    let mut gaps = 0_usize;
    let mut folds = 0_usize;
    for case in corpus["wallResolutions"]
        .as_array()
        .expect("wallResolutions")
    {
        let name = text(case, "zone");
        let probe = text(case, "wall");
        let label = format!("{name} @ {probe}");
        let zone = FireZone::named(&name).expect("a real zone");
        let wall = parse_wall_iso(&probe).unwrap_or_else(|| panic!("{label}: unparseable probe"));
        let resolved = zone.resolve_wall_time(wall);
        match case["instant"].as_str() {
            None => {
                assert!(resolved.is_none(), "{label}: v0 found no instant (a GAP)");
                // RFC 5545 section 3.3.5 (owner decision on #1173): a series
                // moves a gap time FORWARD. `forward` is Python's `fold=0`
                // reading of the same wall clock (PEP 495: the offset before
                // the change), an independent implementation of the RFC's.
                let forward = zone.resolve_wall_time_forward(wall);
                assert_eq!(
                    Some(forward.instant.as_str()),
                    case["forward"].as_str(),
                    "{label}: the RFC's reading of a gap"
                );
                assert!(!forward.overlap, "{label}");
                gaps += 1;
            }
            Some(instant) => {
                let resolved = resolved.unwrap_or_else(|| panic!("{label}: this build found none"));
                assert_eq!(resolved.instant, instant, "{label}: instant");
                let overlap = case["overlap"].as_bool().unwrap_or_default();
                assert_eq!(resolved.overlap, overlap, "{label}: overlap");
                if overlap {
                    folds += 1;
                }
            }
        }
    }
    assert!(gaps > 0, "the corpus contains a gap");
    assert!(folds > 0, "the corpus contains a fold");
}

