#[test]
fn every_missed_collapse_agrees_with_v0() {
    let corpus = fixture("occurrence-cases.json");
    for case in corpus["collapse"].as_array().expect("collapse") {
        let zone = FireZone::named(&text(case, "zone")).expect("a real zone");
        let rrule_text = text(case, "rrule");
        let scheduled = text(case, "scheduledStart");
        let now = text(case, "now");
        let completed = case["lastCompletedAt"].as_str().map(str::to_owned);
        let found = recurrence::collapse_missed(&CollapseInput {
            rrule: &rrule_text,
            scheduled_start: &scheduled,
            zone: Some(&zone),
            anchor: RecurrenceAnchor::from_stored(case["anchor"].as_str()),
            now: &now,
            last_completed_at: completed.as_deref(),
        });
        let want = &case["collapsed"];
        assert_eq!(
            i64::try_from(found.missed).unwrap_or_default(),
            want["missed"].as_i64().unwrap_or_default(),
            "{rrule_text} @ {now}: missed"
        );
        assert_eq!(
            found.next_due.as_deref(),
            want["nextDue"].as_str(),
            "{rrule_text} @ {now}: next due"
        );
    }
}

#[test]
fn every_temporal_classification_agrees_with_v0() {
    let corpus = fixture("occurrence-cases.json");
    let mut seen: BTreeMap<&str, usize> = BTreeMap::new();
    for case in corpus["temporal"].as_array().expect("temporal") {
        let value = text(case, "value");
        let found = temporal::classify(&value).map(temporal::Kind::as_str);
        assert_eq!(found, case["kind"].as_str(), "{value:?}");
        *seen.entry(found.unwrap_or("null")).or_default() += 1;
    }
    assert_eq!(seen.len(), 5, "all four readings and the refusal appear");
}
